def flatten_nested_dict(d: dict, sep: str = ".") -> dict:
    result = {}
    for key, value in d.items():
        if isinstance(value, dict):
            if value:
                sub_dict = flatten_nested_dict(value, sep=sep)
                for sub_key, sub_value in sub_dict.items():
                    result[f"{key}{sep}{sub_key}"] = sub_value
            else:
                result[key] = value
        else:
            result[key] = value
    return result

